                var paginationResult = await labelService.GetPaginatedLabelResult(filterDTO, query);

                lazyLoadSelectedIdsResultDTO.SelectedIds = await paginationResult.Query
                    .Select(x => x.Id)
                    .ToListAsync();

                int count = await _deps.Context.DbSet<Label>()
                    .Where(x => x.Lanes
                        .Any(x => x.Id == filterDTO.AdditionalFilterIdLong))
                    .CountAsync();

                lazyLoadSelectedIdsResultDTO.TotalRecordsSelected = count;
            });

            return lazyLoadSelectedIdsResultDTO;
        }



