        /// <summary>
        /// Updates the many-to-many relationship between BoardLane and Member entities.
        /// Adds new associations and removes unselected ones.
        /// </summary>
        /// <param name="id">The ID of the BoardLane entity</param>
        /// <param name="selectedIds">List of selected Member IDs</param>
        public async virtual Task UpdateMembersForBoardLane(long id, List<long> selectedIds)
        {
            if (selectedIds == null)
                return;

            List<long> selectedIdsHelper = selectedIds.ToList();

            await _deps.Context.WithTransactionAsync(async () =>
            {
                // FT: Not doing authorization here, because we can not figure out here if we are updating while inserting object (eg. User), or updating object, we will always get the id which is not 0 here.

                var entity = await GetInstanceAsync<BoardLane, long>(id, null); // FT: Version will always be checked before or after this method

                foreach (Member item in entity.Members.ToList())
                {
                    if (selectedIdsHelper.Contains(item.Id))
                        selectedIdsHelper.Remove(item.Id);
                    else
                        entity.Members.Remove(item);
                }

                var listToInsert = await _deps.Context.DbSet<Member>().Where(x => selectedIdsHelper.Contains(x.Id)).ToListAsync();

                entity.Members.AddRange(listToInsert);
                await _deps.Context.SaveChangesAsync();
            });
        }

        /// <summary>
        /// Lazy loads selected IDs for many-to-many relationship with pagination support.
        /// IMPORTANT: The query must be ordered by the same field as the table data for correct results.
        /// </summary>
        /// <param name="filterDTO">Filter and pagination parameters</param>
        /// <param name="query">The base query (must be ordered)</param>
        /// <returns>LazyLoadSelectedIdsResultDTO containing selected IDs and total count</returns>
        public async virtual Task<LazyLoadSelectedIdsResultDTO<long>> LazyLoadSelectedMembersIdsForBoardLane(FilterDTO filterDTO, IQueryable<Member> query)
        {
            LazyLoadSelectedIdsResultDTO<long> lazyLoadSelectedIdsResultDTO = new();

            query = query
                .Skip(filterDTO.First)
                .Take(filterDTO.Rows)
                .Where(x => x.Lanes
                    .Any(x => x.Id == filterDTO.AdditionalFilterIdLong));

            await _deps.Context.WithTransactionAsync(async () =>
            {
                var memberService = _deps.ServiceProvider.GetRequiredService<MemberServiceGenerated>();
                var paginationResult = await memberService.GetPaginatedMemberResult(filterDTO, query);

                lazyLoadSelectedIdsResultDTO.SelectedIds = await paginationResult.Query
                    .Select(x => x.Id)
                    .ToListAsync();

                int count = await _deps.Context.DbSet<Member>()
                    .Where(x => x.Lanes
                        .Any(x => x.Id == filterDTO.AdditionalFilterIdLong))
                    .CountAsync();

                lazyLoadSelectedIdsResultDTO.TotalRecordsSelected = count;
            });

            return lazyLoadSelectedIdsResultDTO;
        }



